"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7355],{96709:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PlaceUtility","desc":"Author: Zach Curtis (InfinityDesign)\\n\\nHelper module to check and see what place this code is currently being executed\\nin.\\n\\nWhich place is decided by a `ReplicatedStorage.Environment` StringValue holding\\n`\\"Single\\"`, `\\"Main\\"` or `\\"Level\\"`; whether the run is live is decided by\\ncomparing `game.GameId` against `GameData.liveExperienceId`. Both are read once\\nat require-time and frozen into the returned table, so changing the Environment\\nvalue at runtime has no effect. Any other Environment value warns and leaves all\\nthree place fields `false`.\\n\\nFields:\\n\\n- `isSingle` \u2014 one-place experience: the round loop runs in-place, queue disabled.\\n- `isMain` / `isLevel` \u2014 starter place (queue + hub) / gameplay place of a\\n  2-place experience.\\n- `isProduction` \u2014 `false` in Studio and in the dev universe.\\n- `experienceId`, `placeId`, `levelPlaceId` \u2014 the live or dev ids, picked to match\\n  `isProduction`, so callers never have to branch on the environment themselves.\\n\\n```lua\\nif PlaceUtility.isMain then\\n\\tTeleportService:TeleportAsync(PlaceUtility.levelPlaceId, { player })\\nend\\n```\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":34,"path":"src/Shared/Modules/PlaceUtility.luau"}}')}}]);